package com.eva.ro.contab.component;

import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;
import java.util.function.Function;
import java.util.function.IntBinaryOperator;
import java.util.function.Predicate;

import org.adempiere.base.event.AbstractEventHandler;
import org.adempiere.base.event.IEventTopics;
import org.compiere.model.PO;
import org.compiere.util.DB;
import org.osgi.service.event.Event;

import com.eva.ro.contab.documente.Etichete;
import com.eva.ro.contab.wms.ModelWms;

/**
 * P01.C03.T0029 (P01.T355) A-3 (spec {@code 05_} §3.4, D-04-8 varianta a, D-05a-4) — garda versiunii listei de materiale folosite de
 * stocul WMS: o versiune {@code PP_Product_BOM} pe care stă un set ambalat ({@code EVA_StocWms} cu {@code Qty > 0} pe
 * {@code PP_Product_BOM_ID}) nu se mai schimbă, pe orice cale (fereastra nativă, ecranele EvA, «Rețetă…» T354, REST): antetul nu se
 * șterge, nu se inactivează și nu-și schimbă articolul; liniile nu se adaugă, nu se șterg și nu-și schimbă articolul, cantitatea,
 * activarea, procentul, rebutul sau tipul — altfel dezambalarea ar desface setul în alte piese decât cele ambalate (X139 / X143: refuz
 * explicit, nu pierdere). Decizia: funcția PURĂ {@link #decizie} (X182, D-11c-3), cu cititorul rândurilor de stoc injectat, peste
 * regulile {@link #folosita} și {@link #refuzSchimbare}; o salvare fără efect pe coloanele păzite nu citește baza; {@link #trateaza}
 * emite refuzul; {@code doHandleEvent} doar extrage valorile PO-ului și le predă. Citirea strict pe firma PO-ului ({@code AD_Client_ID = ?}); firma System ⇒ nimic de păzit (stocul WMS e pe firmă).
 * Înregistrat în {@code EvaActivator} (blocul {@code # P01.T355}).
 */
public class EvaNotaSetBomEvents extends AbstractEventHandler {

    public static final String BOM = "PP_Product_BOM", LINIE = "PP_Product_BOMLine";
    public static final String R_LISTA_FOLOSITA = "t355.refuz.lista_folosita";
    /** Coloanele liniei păzite la schimbare (plus mutarea liniei pe altă versiune, {@code PP_Product_BOM_ID}). */
    public static final List<String> COLOANE_LINIE = List.of("M_Product_ID", "QtyBOM", "IsActive", "IsQtyPercentage", "Scrap",
            "ComponentType", "PP_Product_BOM_ID");
    public static final List<String> EVENIMENTE = List.of(IEventTopics.PO_BEFORE_NEW, IEventTopics.PO_BEFORE_CHANGE,
            IEventTopics.PO_BEFORE_DELETE);

    /** Versiunea e folosită de stocul WMS: un rând {@code EVA_StocWms} cu cantitate pozitivă; parametri: ad_client_id, versiunea. */
    public static final String SQL_FOLOSITA = "SELECT count(*) FROM " + ModelWms.STOC + " WHERE AD_Client_ID=? AND PP_Product_BOM_ID=? AND Qty>0";

    @Override
    protected void initialize() {
        for (String e : EVENIMENTE) {
            registerTableEvent(e, BOM);
            registerTableEvent(e, LINIE);
        }
    }

    /** PUR: versiunea e folosită ⇔ cel puțin un rând de stoc pozitiv. */
    static boolean folosita(int randuri) {
        return randuri > 0;
    }

    /**
     * PUR: cheia refuzului sau {@code null}. Permis: versiunea nefolosită; o schimbare fără efect pe coloanele păzite; antetul nou (o
     * versiune nouă nu poate fi încă folosită). Refuzat, pe o versiune folosită: orice ștergere, linia nouă, schimbarea cu efect.
     */
    static String refuzSchimbare(String tabela, String eveniment, boolean folosita, boolean doarActualizareFaraEfect) {
        if (!folosita || doarActualizareFaraEfect)
            return null;
        if (!BOM.equals(tabela) && !LINIE.equals(tabela))
            return null;
        if (BOM.equals(tabela) && IEventTopics.PO_BEFORE_NEW.equals(eveniment))
            return null;
        return R_LISTA_FOLOSITA;
    }

    /**
     * PUR: schimbarea ({@code PO_BEFORE_CHANGE}) nu atinge coloanele păzite — antetul: articolul și inactivarea ({@code IsActive} → N);
     * linia: {@link #COLOANE_LINIE}. Celelalte evenimente au mereu efect.
     */
    static boolean faraEfect(String tabela, String eveniment, Predicate<String> schimbat, Function<String, Object> valoare) {
        if (!IEventTopics.PO_BEFORE_CHANGE.equals(eveniment))
            return false;
        if (BOM.equals(tabela))
            return !schimbat.test("M_Product_ID") && !(schimbat.test("IsActive") && !EvaWmsGardaEvents.da(valoare.apply("IsActive")));
        for (String c : COLOANE_LINIE)
            if (schimbat.test(c))
                return false;
        return true;
    }

    private static int intreg(Object o) {
        return o instanceof Number n ? n.intValue() : 0;
    }

    /**
     * PUR (X182, D-11c-3): cheia refuzului sau {@code null}, pentru evenimentul {@code topic} pe {@code tabela}, PO-ul firmei {@code client}
     * cu id-ul {@code id}; la linie {@code bom} = versiunea curentă, {@code bomVechi} = versiunea dinaintea schimbării. Versiunile
     * verificate: antetul ⇒ {@code id}; linia ⇒ {@code bom} și, la mutarea pe altă versiune ({@code PO_BEFORE_CHANGE} cu
     * {@code PP_Product_BOM_ID} schimbat), și {@code bomVechi}. {@code randuri.applyAsInt(client, versiune)} = rândurile de stoc pozitiv
     * ({@link #SQL_FOLOSITA}); necitit pe firma System, pe antetul nou și pe o schimbare fără efect.
     */
    static String decizie(String tabela, String topic, int client, int id, int bom, int bomVechi, Predicate<String> schimbat,
            Function<String, Object> valoare, IntBinaryOperator randuri) {
        if (client <= 0 || BOM.equals(tabela) && IEventTopics.PO_BEFORE_NEW.equals(topic))
            return null;
        if (faraEfect(tabela, topic, schimbat, valoare))
            return null;
        Set<Integer> versiuni = new LinkedHashSet<>();
        if (BOM.equals(tabela))
            versiuni.add(id);
        else {
            versiuni.add(bom);
            if (IEventTopics.PO_BEFORE_CHANGE.equals(topic) && schimbat.test("PP_Product_BOM_ID"))
                versiuni.add(bomVechi);
        }
        for (int v : versiuni) {
            if (v <= 0)
                continue;
            String r = refuzSchimbare(tabela, topic, folosita(randuri.applyAsInt(client, v)), false);
            if (r != null)
                return r;
        }
        return null;
    }

    /** Decizia ({@link #decizie}) pe evenimentul primit și emiterea refuzului tradus în mesajele de eroare ale evenimentului. */
    void trateaza(Event event, String tabela, int client, int id, int bom, int bomVechi, Predicate<String> schimbat,
            Function<String, Object> valoare, IntBinaryOperator randuri) {
        String r = decizie(tabela, event.getTopic(), client, id, bom, bomVechi, schimbat, valoare, randuri);
        if (r != null)
            addErrorMessage(event, Etichete.t(r));
    }

    @Override
    protected void doHandleEvent(Event event) {
        PO po = getPO(event);
        String trx = po.get_TrxName();
        trateaza(event, po.get_TableName(), po.getAD_Client_ID(), po.get_ID(), intreg(po.get_Value("PP_Product_BOM_ID")),
                intreg(po.get_ValueOld("PP_Product_BOM_ID")), po::is_ValueChanged, po::get_Value,
                (c, v) -> DB.getSQLValueEx(trx, SQL_FOLOSITA, c, v));
    }
}

package com.eva.ro.contab.wms;

import java.math.BigDecimal;
import java.util.LinkedHashMap;
import java.util.Map;

import org.compiere.model.MProduct;
import org.compiere.util.Env;
import org.eevolution.model.MPPProductBOM;
import org.eevolution.model.MPPProductBOMLine;

/**
 * P01.C03.T0017 (P01.T331) A-4 (04_ F-5 / F-6) — lista de materiale a unui set din stocul validat: piesă → bucăți, pe versiunea
 * {@code PP_Product_BOM_ID} păstrată la ambalare (09_ D-7). Punctul de legătură cu T354 (varianta pe versiuni), fără schimbarea semnăturii.
 */
public interface ListaMaterialeWms {

    /** Piesele setului {@code set} pe versiunea {@code bom}: produs → bucăți într-un set. */
    Map<Integer, BigDecimal> piese(int client, int set, int bom, String trx);

    /**
     * Implicitul: versiunea dată ({@code bom > 0}) sau lista nativă implicită a produsului ({@code MPPProductBOM.getDefault},
     * ca {@code WProduseForm}); liniile active, bucățile adunate pe piesă. O listă a altei firme nu se citește (firma explicită).
     */
    ListaMaterialeWms IMPLICIT = (client, set, bom, trx) -> {
        if (client <= 0)
            throw new IllegalArgumentException("AD_Client_ID " + client);
        MPPProductBOM b = bom > 0 ? new MPPProductBOM(Env.getCtx(), bom, trx) : MPPProductBOM.getDefault(MProduct.get(Env.getCtx(), set), trx);
        Map<Integer, BigDecimal> m = new LinkedHashMap<>();
        if (b == null || b.get_ID() <= 0 || b.getAD_Client_ID() != client)
            return m;
        for (MPPProductBOMLine l : b.getLines())
            if (l.isActive())
                m.merge(l.getM_Product_ID(), l.getQtyBOM(), BigDecimal::add);
        return m;
    };
}

