    /** P01.T327: pune implicitul pe parametrul procesului DOAR dacă lipsește (prin PO, nu prin UPDATE; idempotent). */
    private static void implicitT327(Properties ctx, String trxName, int processId, String col, String implicit) {
        int id = DB.getSQLValueEx(trxName,
                "SELECT ad_process_para_id FROM ad_process_para WHERE ad_process_id=? AND columnname=?", processId, col);
        if (id <= 0)
            return;
        MProcessPara pp = new MProcessPara(ctx, id, trxName);
        if (pp.getDefaultValue() != null && !pp.getDefaultValue().isEmpty())
            return;
        pp.setDefaultValue(implicit);
        pp.saveEx();
    }
